// ============================================================================
// FVX Invariant Checker (정형 검증 - 불변량 검사자)
// FreeLang 구현 - Zero-Copy DB 안전성 증명
// ============================================================================
//
// 목표: Zero-Copy 포인터 연산이 절대 버퍼 범위를 벗어나지 않음을
//       수학적으로 증명
//
// 원리:
//   - Boundary Invariant: ptr ∈ [buffer.start, buffer.end]
//   - Every allocation has (start, size) → end = start + size
//   - Pointer arithmetic: new_ptr = ptr + offset
//   - Verification: new_ptr >= start && new_ptr <= end (또는 end - ptr <= size)
//
// 형식화:
//   Inv1: ∀allocation(start, size). size > 0
//   Inv2: ∀ptr. ptr >= start && ptr <= (start + size)
//   Inv3: ∀(ptr + offset). (ptr + offset) >= start && (ptr + offset) <= (start + size)
// ============================================================================

module fvx {
    // ========================================================================
    // 데이터 구조
    // ========================================================================

    // BufferBound는 할당된 메모리 버퍼의 경계를 나타냄
    struct BufferBound {
        buffer_start: u64;      // 버퍼 시작 주소
        buffer_size: u64;       // 버퍼 크기 (바이트)
        buffer_end: u64;        // 버퍼 끝 주소 (start + size)
        allocation_id: u32;     // 할당 ID (추적용)
        is_valid: bool;         // 유효한 할당인지 여부
    }

    // PointerContext는 포인터 연산의 컨텍스트
    struct PointerContext {
        ptr: u64;               // 현재 포인터
        bound: BufferBound;     // 해당 버퍼 경계
        offset: i64;            // 마지막 오프셋 연산
        is_in_bounds: bool;     // 범위 내인지
    }

    // InvariantViolation은 불변량 위반 정보
    struct InvariantViolation {
        violation_type: u32;    // 위반 유형 (1=out_of_bounds, 2=neg_offset, 3=corrupt)
        ptr: u64;               // 문제가 된 포인터
        bound_start: u64;       // 경계 시작
        bound_end: u64;         // 경계 끝
        expected_range: (u64, u64);  // 예상 범위
        message: string;        // 위반 메시지
    }

    // ============================================================================
    // 불변량 1: 할당 유효성 검증
    // ============================================================================

    // is_valid_allocation: 할당이 기본 조건을 만족하는가?
    // Inv1: size > 0
    func is_valid_allocation(start: u64, size: u64) -> bool {
        // 조건 1: size > 0
        if size == 0 {
            return false;
        }

        // 조건 2: start + size 오버플로우 체크
        // (u64 범위를 벗어나면 안됨)
        let end = start + size;
        if end < start {  // 오버플로우 발생
            return false;
        }

        // 조건 3: start는 페이지 정렬되어야 함 (선택사항)
        // 64바이트 최소 정렬 검증
        let aligned = start % 64;
        if aligned != 0 {
            return false;
        }

        return true;
    }

    // ============================================================================
    // 불변량 2: 포인터가 범위 내인가?
    // ============================================================================

    // is_in_bounds: 포인터가 할당된 버퍼 범위 내인가?
    // Inv2: ptr >= start && ptr <= end
    @inline
    func is_in_bounds(ptr: u64, bound: BufferBound) -> bool {
        return ptr >= bound.buffer_start && ptr <= bound.buffer_end;
    }

    // calc_offset_from_start: 버퍼 시작으로부터의 오프셋
    @inline
    func calc_offset_from_start(ptr: u64, bound: BufferBound) -> i64 {
        if !is_in_bounds(ptr, bound) {
            return -1;  // 범위 외
        }
        return i64(ptr - bound.buffer_start);
    }

    // remaining_bytes: 현재 포인터에서 끝까지의 남은 바이트
    @inline
    func remaining_bytes(ptr: u64, bound: BufferBound) -> i64 {
        if !is_in_bounds(ptr, bound) {
            return -1;  // 범위 외
        }
        return i64(bound.buffer_end - ptr);
    }

    // ============================================================================
    // 불변량 3: 포인터 연산의 경계 보존
    // ============================================================================

    // verify_pointer_arithmetic: ptr + offset이 범위 내인가?
    // Inv3: (ptr + offset) ∈ [start, end]
    // 즉, start <= ptr + offset <= end
    @inline
    func verify_pointer_arithmetic(ptr: u64, offset: i64, bound: BufferBound) -> (bool, InvariantViolation) {
        // 1단계: 기본 경계 검사
        if !bound.is_valid {
            let violation = InvariantViolation {
                violation_type: 3,
                ptr: ptr,
                bound_start: bound.buffer_start,
                bound_end: bound.buffer_end,
                expected_range: (bound.buffer_start, bound.buffer_end),
                message: "Buffer bound is invalid",
            };
            return (false, violation);
        }

        // 2단계: 시작 포인터가 범위 내인가?
        if !is_in_bounds(ptr, bound) {
            let violation = InvariantViolation {
                violation_type: 1,
                ptr: ptr,
                bound_start: bound.buffer_start,
                bound_end: bound.buffer_end,
                expected_range: (bound.buffer_start, bound.buffer_end),
                message: "Start pointer out of bounds",
            };
            return (false, violation);
        }

        // 3단계: 오프셋 후 포인터 계산
        let new_ptr: i64 = i64(ptr) + offset;

        // 4단계: 결과가 음수인가? (바운더리 이전으로)
        if new_ptr < i64(bound.buffer_start) {
            let violation = InvariantViolation {
                violation_type: 1,
                ptr: u64(new_ptr),
                bound_start: bound.buffer_start,
                bound_end: bound.buffer_end,
                expected_range: (bound.buffer_start, bound.buffer_end),
                message: "Pointer arithmetic underflow (negative offset too large)",
            };
            return (false, violation);
        }

        // 5단계: 결과가 끝을 넘는가?
        let new_ptr_u64 = u64(new_ptr);
        if new_ptr_u64 > bound.buffer_end {
            let violation = InvariantViolation {
                violation_type: 1,
                ptr: new_ptr_u64,
                bound_start: bound.buffer_start,
                bound_end: bound.buffer_end,
                expected_range: (bound.buffer_start, bound.buffer_end),
                message: "Pointer arithmetic overflow (positive offset too large)",
            };
            return (false, violation);
        }

        // 성공: 새 포인터가 범위 내
        let violation = InvariantViolation {
            violation_type: 0,
            ptr: new_ptr_u64,
            bound_start: bound.buffer_start,
            bound_end: bound.buffer_end,
            expected_range: (bound.buffer_start, bound.buffer_end),
            message: "Pointer arithmetic verified",
        };
        return (true, violation);
    }

    // ============================================================================
    // 배열 범위 검증
    // ============================================================================

    // verify_array_access: 배열 인덱스가 범위 내인가?
    // arr[index]가 유효한가? → ptr + (index * element_size) <= end
    @inline
    func verify_array_access(ptr: u64, index: u64, element_size: u64, bound: BufferBound) -> (bool, InvariantViolation) {
        // 오버플로우 체크: index * element_size
        let offset: i64 = i64(index * element_size);
        return verify_pointer_arithmetic(ptr, offset, bound);
    }

    // verify_array_slice: 배열 슬라이스가 범위 내인가?
    // arr[start_idx:end_idx]가 유효한가?
    @inline
    func verify_array_slice(ptr: u64, start_idx: u64, end_idx: u64, element_size: u64, bound: BufferBound) -> (bool, InvariantViolation) {
        // start 인덱스 검증
        let start_offset: i64 = i64(start_idx * element_size);
        let (start_ok, start_violation) = verify_pointer_arithmetic(ptr, start_offset, bound);
        if !start_ok {
            return (false, start_violation);
        }

        // end 인덱스 검증
        let end_offset: i64 = i64(end_idx * element_size);
        let (end_ok, end_violation) = verify_pointer_arithmetic(ptr, end_offset, bound);
        return (end_ok, end_violation);
    }

    // ============================================================================
    // 스택 기반 불변량 추적기
    // ============================================================================

    // InvariantTracker는 실행 중 불변량 위반을 추적
    struct InvariantTracker {
        allocations: [BufferBound];              // 할당된 버퍼 목록
        pointer_contexts: [PointerContext];      // 포인터 컨텍스트 추적
        violations: [InvariantViolation];        // 발견된 위반
        is_tracking: bool;                       // 추적 중인가?
    }

    // tracker_new: 새로운 추적기 생성
    func tracker_new() -> InvariantTracker {
        return InvariantTracker {
            allocations: make([BufferBound], 0),
            pointer_contexts: make([PointerContext], 0),
            violations: make([InvariantViolation], 0),
            is_tracking: true,
        };
    }

    // tracker_add_allocation: 할당 추적
    func (t: *InvariantTracker) tracker_add_allocation(start: u64, size: u64, id: u32) -> bool {
        if !t.is_tracking {
            return false;
        }

        if !is_valid_allocation(start, size) {
            return false;
        }

        let bound = BufferBound {
            buffer_start: start,
            buffer_size: size,
            buffer_end: start + size,
            allocation_id: id,
            is_valid: true,
        };

        t.allocations.push(bound);
        return true;
    }

    // tracker_track_pointer: 포인터 추적
    func (t: *InvariantTracker) tracker_track_pointer(ptr: u64, allocation_id: u32) -> bool {
        if !t.is_tracking {
            return false;
        }

        // 해당 할당 찾기
        let bound: BufferBound;
        let found = false;

        for i = 0; i < len(t.allocations); i = i + 1 {
            if t.allocations[i].allocation_id == allocation_id {
                bound = t.allocations[i];
                found = true;
                break;
            }
        }

        if !found {
            return false;
        }

        // 포인터가 범위 내인지 확인
        let in_bounds = is_in_bounds(ptr, bound);

        let ctx = PointerContext {
            ptr: ptr,
            bound: bound,
            offset: 0,
            is_in_bounds: in_bounds,
        };

        t.pointer_contexts.push(ctx);
        return true;
    }

    // tracker_verify_arithmetic: 포인터 연산 검증
    func (t: *InvariantTracker) tracker_verify_arithmetic(ptr: u64, offset: i64, allocation_id: u32) -> bool {
        if !t.is_tracking {
            return false;
        }

        // 해당 할당 찾기
        let found = false;
        let bound: BufferBound;

        for i = 0; i < len(t.allocations); i = i + 1 {
            if t.allocations[i].allocation_id == allocation_id {
                bound = t.allocations[i];
                found = true;
                break;
            }
        }

        if !found {
            return false;
        }

        // 포인터 연산 검증
        let (ok, violation) = verify_pointer_arithmetic(ptr, offset, bound);

        if !ok {
            t.violations.push(violation);
        }

        return ok;
    }

    // tracker_get_violations: 모든 위반 반환
    func (t: *InvariantTracker) tracker_get_violations() -> [InvariantViolation] {
        return t.violations;
    }

    // tracker_clear_violations: 위반 목록 초기화
    func (t: *InvariantTracker) tracker_clear_violations() {
        t.violations = make([InvariantViolation], 0);
    }

    // tracker_report: 위반 리포트
    func (t: *InvariantTracker) tracker_report() {
        if len(t.violations) == 0 {
            print("✅ Invariant Checker: All boundary invariants verified!");
            return;
        }

        print("❌ Invariant Checker: Found " + len(t.violations) + " violation(s)");
        print("");

        for i = 0; i < len(t.violations); i = i + 1 {
            let v = t.violations[i];
            print("Violation #" + (i + 1) + ":");
            print("  Type: " + v.violation_type);
            print("  Pointer: " + v.ptr);
            print("  Bound: [" + v.bound_start + ", " + v.bound_end + "]");
            print("  Message: " + v.message);
            print("");
        }
    }
}

// ============================================================================
// 테스트 코드
// ============================================================================

func main() {
    print("🚀 FVX Invariant Checker 테스트");
    print("==================================");
    print("");

    // 테스트 1: 할당 유효성
    print("✅ 테스트 1: 할당 유효성 검증");
    let valid1 = fvx.is_valid_allocation(0, 100);
    print("   is_valid_allocation(0, 100) = " + valid1);
    let valid2 = fvx.is_valid_allocation(0, 0);
    print("   is_valid_allocation(0, 0) = " + valid2);
    print("");

    // 테스트 2: 포인터 범위 검증
    print("✅ 테스트 2: 포인터 범위 검증");
    let bound = fvx.BufferBound {
        buffer_start: 1000,
        buffer_size: 100,
        buffer_end: 1100,
        allocation_id: 1,
        is_valid: true,
    };
    let in_bounds1 = fvx.is_in_bounds(1050, bound);
    print("   is_in_bounds(1050, [1000, 1100]) = " + in_bounds1);
    let in_bounds2 = fvx.is_in_bounds(1150, bound);
    print("   is_in_bounds(1150, [1000, 1100]) = " + in_bounds2);
    print("");

    // 테스트 3: 포인터 연산 검증
    print("✅ 테스트 3: 포인터 연산 검증");
    let (ok1, v1) = fvx.verify_pointer_arithmetic(1000, 50, bound);
    print("   ptr + 50 = " + (1000 + 50) + " → " + ok1);
    let (ok2, v2) = fvx.verify_pointer_arithmetic(1000, 200, bound);
    print("   ptr + 200 = " + (1000 + 200) + " → " + ok2);
    print("");

    // 테스트 4: 배열 접근 검증
    print("✅ 테스트 4: 배열 접근 검증");
    let (ok3, v3) = fvx.verify_array_access(1000, 5, 8, bound);  // 5 * 8 = 40
    print("   arr[5] (element_size=8) → " + ok3);
    let (ok4, v4) = fvx.verify_array_access(1000, 50, 8, bound);  // 50 * 8 = 400
    print("   arr[50] (element_size=8) → " + ok4);
    print("");

    // 테스트 5: InvariantTracker
    print("✅ 테스트 5: InvariantTracker");
    let tracker = fvx.tracker_new();
    tracker.tracker_add_allocation(2000, 200, 1);
    tracker.tracker_add_allocation(3000, 300, 2);
    print("   Added 2 allocations");

    tracker.tracker_track_pointer(2050, 1);
    tracker.tracker_track_pointer(3100, 2);
    print("   Tracked 2 pointers");

    let ok5 = tracker.tracker_verify_arithmetic(2050, 100, 1);  // 2050 + 100 = 2150 (valid)
    print("   Verified arithmetic: 2050 + 100 → " + ok5);

    let ok6 = tracker.tracker_verify_arithmetic(2050, 500, 1);  // 2050 + 500 = 2550 (invalid)
    print("   Verified arithmetic: 2050 + 500 → " + ok6);

    print("   Violations found: " + len(tracker.tracker_get_violations()));
    print("");

    // 테스트 6: 리포트
    print("✅ 테스트 6: 불변량 리포트");
    tracker.tracker_report();

    print("");
    print("✨ FVX Invariant Checker 테스트 완료!");
}

