// ============================================================================
// FVX Race Condition Detector (정형 검증 - 경쟁 상태 검출기)
// FreeLang 구현 - 동시성 안전성 증명
// ============================================================================
//
// 목표: 멀티코어 환경에서 동일한 메모리 주소에 대한 동시 쓰기가
//       발생할 수 없음을 정적 분석 단계에서 확정
//
// 원리:
//   - Happens-Before Relation: 각 메모리 접근의 타이밍 관계
//   - Memory Access History: 어떤 스레드가 언제 어디에 접근했는가
//   - Conflict Detection: Write-Write, Read-Write 동시성 감지
//   - Ownership Model: 특정 스레드만이 메모리에 접근 가능
//
// 형식화:
//   Access = (thread_id, address, operation, timestamp, lock_held)
//   Conflict = (access1, access2) where:
//     - address1 == address2 (같은 메모리 주소)
//     - (op1 == WRITE || op2 == WRITE) (쓰기 포함)
//     - No Synchronization (같은 lock 없음)
//
// 검증 목표:
//   ∀(access1, access2) ∈ History.
//     (addr(access1) == addr(access2) ∧ isWrite(access1 ∨ access2))
//       → (happens_before(access1, access2) ∨ happens_before(access2, access1)
//          ∨ same_lock(access1, access2))
// ============================================================================

module fvx {
    // ========================================================================
    // 상수
    // ========================================================================

    const OP_READ: u32 = 1;
    const OP_WRITE: u32 = 2;
    const OP_LOCK: u32 = 3;
    const OP_UNLOCK: u32 = 4;

    // ========================================================================
    // 데이터 구조
    // ========================================================================

    // MemoryAccess는 메모리 접근 기록
    struct MemoryAccess {
        thread_id: u32;         // 접근한 스레드 ID
        address: u64;           // 메모리 주소
        operation: u32;         // OP_READ, OP_WRITE, OP_LOCK, OP_UNLOCK
        timestamp: u64;         // 논리적 타임스탬프 (벡터 클록)
        lock_id: u32;           // 보유한 락 ID (0 = 없음)
        instruction_id: u64;    // 명령어 ID (프로그램 순서)
        is_volatile: bool;      // volatile 변수인가?
    }

    // RaceCondition은 경쟁 상태 발견
    struct RaceCondition {
        access1: MemoryAccess;
        access2: MemoryAccess;
        conflict_type: u32;     // 1=Read-Write, 2=Write-Write
        same_address: bool;
        synchronized: bool;     // 동기화되었는가?
        message: string;
    }

    // ThreadState는 각 스레드의 상태
    struct ThreadState {
        thread_id: u32;
        lock_ids: [u32];        // 현재 보유한 락 목록
        last_timestamp: u64;    // 마지막 접근 타임스탬프
        access_count: u32;      // 총 접근 횟수
    }

    // LockState는 락의 상태
    struct LockState {
        lock_id: u32;
        owner_thread: u32;      // 현재 소유 스레드 (0 = free)
        acquisition_count: u32; // 획득 횟수
    }

    // ========================================================================
    // 기본 검증 함수
    // ========================================================================

    // is_write_operation: 쓰기 연산인가?
    @inline
    func is_write_operation(op: u32) -> bool {
        return op == OP_WRITE;
    }

    // is_read_operation: 읽기 연산인가?
    @inline
    func is_read_operation(op: u32) -> bool {
        return op == OP_READ;
    }

    // is_sync_operation: 동기화 연산인가? (락)
    @inline
    func is_sync_operation(op: u32) -> bool {
        return op == OP_LOCK || op == OP_UNLOCK;
    }

    // same_lock: 두 접근이 같은 락으로 보호되는가?
    @inline
    func same_lock(lock1: u32, lock2: u32) -> bool {
        return lock1 != 0 && lock1 == lock2;
    }

    // ========================================================================
    // Happens-Before 관계
    // ========================================================================

    // happens_before: access1이 access2보다 논리적으로 먼저 일어났는가?
    // 조건:
    //   1. 같은 스레드 내: instruction_id 비교
    //   2. 다른 스레드: synchronization point 추적
    @inline
    func happens_before(a1: MemoryAccess, a2: MemoryAccess) -> bool {
        // 같은 스레드 내에서는 instruction_id로 비교
        if a1.thread_id == a2.thread_id {
            return a1.instruction_id < a2.instruction_id;
        }

        // 다른 스레드: 타임스탬프로 비교 (vector clock simulation)
        return a1.timestamp < a2.timestamp;
    }

    // ========================================================================
    // 경쟁 상태 감지
    // ========================================================================

    // has_data_race: 두 접근 사이에 경쟁 상태가 있는가?
    func has_data_race(a1: MemoryAccess, a2: MemoryAccess) -> bool {
        // 조건 1: 같은 메모리 주소
        if a1.address != a2.address {
            return false;
        }

        // 조건 2: 둘 다 volatile 변수가 아님 (volatile은 race 없음)
        if a1.is_volatile && a2.is_volatile {
            return false;
        }

        // 조건 3: 적어도 하나는 쓰기
        let is_conflict = is_write_operation(a1.operation) || is_write_operation(a2.operation);
        if !is_conflict {
            return false;  // 읽기-읽기는 race 아님
        }

        // 조건 4: 같은 락으로 보호되지 않음
        if same_lock(a1.lock_id, a2.lock_id) {
            return false;  // 같은 락으로 보호됨
        }

        // 조건 5: happens-before 관계가 없음 (동시성)
        let a1_before_a2 = happens_before(a1, a2);
        let a2_before_a1 = happens_before(a2, a1);

        if a1_before_a2 || a2_before_a1 {
            return false;  // happens-before 관계 있음
        }

        // 모든 조건 위반 → 경쟁 상태 있음
        return true;
    }

    // ========================================================================
    // Race Detector
    // ========================================================================

    // RaceDetector는 실행 중 경쟁 상태를 감지
    struct RaceDetector {
        accesses: [MemoryAccess];           // 모든 메모리 접근 기록
        races: [RaceCondition];             // 발견된 경쟁 상태
        thread_states: [ThreadState];       // 각 스레드의 상태
        lock_states: [LockState];           // 락 상태
        is_detecting: bool;                 // 감지 중인가?
    }

    // detector_new: 새로운 감지기 생성
    func detector_new() -> RaceDetector {
        return RaceDetector {
            accesses: make([MemoryAccess], 0),
            races: make([RaceCondition], 0),
            thread_states: make([ThreadState], 0),
            lock_states: make([LockState], 0),
            is_detecting: true,
        };
    }

    // detector_register_thread: 스레드 등록
    func (d: *RaceDetector) detector_register_thread(thread_id: u32) -> bool {
        if !d.is_detecting {
            return false;
        }

        let state = ThreadState {
            thread_id: thread_id,
            lock_ids: make([u32], 0),
            last_timestamp: 0,
            access_count: 0,
        };

        d.thread_states.push(state);
        return true;
    }

    // detector_register_lock: 락 등록
    func (d: *RaceDetector) detector_register_lock(lock_id: u32) -> bool {
        if !d.is_detecting {
            return false;
        }

        let state = LockState {
            lock_id: lock_id,
            owner_thread: 0,
            acquisition_count: 0,
        };

        d.lock_states.push(state);
        return true;
    }

    // detector_record_access: 메모리 접근 기록
    func (d: *RaceDetector) detector_record_access(
        thread_id: u32,
        address: u64,
        operation: u32,
        lock_id: u32,
        is_volatile: bool
    ) -> bool {
        if !d.is_detecting {
            return false;
        }

        // 타임스탬프 계산 (벡터 클록 단순화)
        let timestamp = u64(len(d.accesses));

        let access = MemoryAccess {
            thread_id: thread_id,
            address: address,
            operation: operation,
            timestamp: timestamp,
            lock_id: lock_id,
            instruction_id: u64(len(d.accesses)),
            is_volatile: is_volatile,
        };

        d.accesses.push(access);

        // 이전 접근들과 비교하여 경쟁 상태 검출
        for i = 0; i < len(d.accesses) - 1; i = i + 1 {
            let prev_access = d.accesses[i];

            if has_data_race(prev_access, access) {
                let race = RaceCondition {
                    access1: prev_access,
                    access2: access,
                    conflict_type: if is_write_operation(prev_access.operation) &&
                                      is_write_operation(access.operation) { 2 } else { 1 },
                    same_address: true,
                    synchronized: false,
                    message: "Data race detected",
                };

                d.races.push(race);
            }
        }

        return true;
    }

    // detector_acquire_lock: 락 획득 기록
    func (d: *RaceDetector) detector_acquire_lock(thread_id: u32, lock_id: u32) -> bool {
        if !d.is_detecting {
            return false;
        }

        // 스레드 상태 업데이트
        for i = 0; i < len(d.thread_states); i = i + 1 {
            if d.thread_states[i].thread_id == thread_id {
                d.thread_states[i].lock_ids.push(lock_id);
                break;
            }
        }

        // 락 상태 업데이트
        for i = 0; i < len(d.lock_states); i = i + 1 {
            if d.lock_states[i].lock_id == lock_id {
                d.lock_states[i].owner_thread = thread_id;
                d.lock_states[i].acquisition_count = d.lock_states[i].acquisition_count + 1;
                break;
            }
        }

        // 동기화 이벤트 기록
        return d.detector_record_access(thread_id, 0, OP_LOCK, lock_id, false);
    }

    // detector_release_lock: 락 해제 기록
    func (d: *RaceDetector) detector_release_lock(thread_id: u32, lock_id: u32) -> bool {
        if !d.is_detecting {
            return false;
        }

        // 스레드 상태 업데이트 (간단한 구현)
        for i = 0; i < len(d.thread_states); i = i + 1 {
            if d.thread_states[i].thread_id == thread_id {
                // lock_ids에서 제거 (간단한 방식)
                break;
            }
        }

        // 락 상태 업데이트
        for i = 0; i < len(d.lock_states); i = i + 1 {
            if d.lock_states[i].lock_id == lock_id {
                d.lock_states[i].owner_thread = 0;
                break;
            }
        }

        // 동기화 이벤트 기록
        return d.detector_record_access(thread_id, 0, OP_UNLOCK, lock_id, false);
    }

    // detector_get_races: 발견된 경쟁 상태 반환
    func (d: *RaceDetector) detector_get_races() -> [RaceCondition] {
        return d.races;
    }

    // detector_has_races: 경쟁 상태가 있는가?
    func (d: *RaceDetector) detector_has_races() -> bool {
        return len(d.races) > 0;
    }

    // detector_report: 경쟁 상태 리포트
    func (d: *RaceDetector) detector_report() {
        if len(d.races) == 0 {
            print("✅ Race Detector: No data races detected!");
            print("");
            print("   Summary:");
            print("   - Total accesses: " + len(d.accesses));
            print("   - Threads: " + len(d.thread_states));
            print("   - Locks: " + len(d.lock_states));
            return;
        }

        print("❌ Race Detector: Found " + len(d.races) + " potential data race(s)");
        print("");

        for i = 0; i < len(d.races); i = i + 1 {
            let race = d.races[i];
            print("Race #" + (i + 1) + ":");
            print("  Address: " + race.access1.address);
            print("  Thread 1: " + race.access1.thread_id);
            print("    Operation: " + race.access1.operation);
            print("    Lock: " + race.access1.lock_id);
            print("  Thread 2: " + race.access2.thread_id);
            print("    Operation: " + race.access2.operation);
            print("    Lock: " + race.access2.lock_id);
            print("  Type: " + if race.conflict_type == 1 { "Read-Write" } else { "Write-Write" });
            print("  Message: " + race.message);
            print("");
        }
    }

    // ========================================================================
    // 정적 분석: 소유권 모델
    // ========================================================================

    // OwnershipModel은 메모리 소유권을 추적
    struct OwnershipModel {
        address: u64;           // 메모리 주소
        owner_thread: u32;      // 소유 스레드
        access_lock: u32;       // 접근 보호 락
        exclusive: bool;        // 배타적 소유인가?
        is_owned: bool;         // 소유되고 있는가?
    }

    // verify_ownership: 메모리 소유권 검증
    // → 특정 스레드만이 메모리에 접근 가능
    func verify_ownership(access: MemoryAccess, ownership: OwnershipModel) -> bool {
        // 조건 1: 소유되지 않은 메모리
        if !ownership.is_owned {
            return true;  // 누구나 접근 가능 (공유 메모리)
        }

        // 조건 2: 배타적 소유 → 소유자만 접근
        if ownership.exclusive {
            return access.thread_id == ownership.owner_thread;
        }

        // 조건 3: 같은 락으로 보호되는가?
        if ownership.access_lock != 0 {
            return access.lock_id == ownership.access_lock;
        }

        return true;
    }
}

