// ============================================================================
// FVX Safety Annotations (정형 검증 - 안전성 주석)
// FreeLang 구현 - 계약 기반 프로그래밍 (Design by Contract)
// ============================================================================
//
// 목표: @require, @ensure, @invariant 주석을 통해
//       함수의 사전조건(Precondition), 사후조건(Postcondition),
//       불변량(Invariant)을 명시적으로 정의하고 검증
//
// 원리:
//   - Precondition (@require): 호출자가 만족해야 할 조건
//   - Postcondition (@ensure): 함수가 보장할 조건
//   - Invariant (@invariant): 항상 참이어야 할 조건
//   - Verification: 런타임 확인 또는 정적 증명
//
// 형식화:
//   @require(condition) → condition == true 또는 panic
//   @ensure(condition) → condition == true 또는 panic (함수 반환 전)
//   @invariant(condition) → 메서드 진입/종료 시마다 검증
//
// 예시:
//   ```freelang
//   @require(ptr != 0)
//   @require(size > 0)
//   @ensure(return != 0)
//   func allocate(size: u32) -> u64 { ... }
//   ```
// ============================================================================

module fvx {
    // ========================================================================
    // 데이터 구조
    // ========================================================================

    // ContractViolation은 계약 위반 정보
    struct ContractViolation {
        violation_type: u32;    // 1=precondition, 2=postcondition, 3=invariant
        function_name: string;
        condition: string;
        actual_value: string;
        expected_value: string;
        message: string;
    }

    // ContractChecker는 계약 검증
    struct ContractChecker {
        violations: [ContractViolation];
        function_depth: u32;    // 함수 호출 깊이
        is_checking: bool;
    }

    // ========================================================================
    // 상수
    // ========================================================================

    const VIOLATION_PRECONDITION: u32 = 1;
    const VIOLATION_POSTCONDITION: u32 = 2;
    const VIOLATION_INVARIANT: u32 = 3;

    // ========================================================================
    // 기본 검증 함수
    // ========================================================================

    // require: 사전조건 검증
    // @require(condition) → condition이 거짓이면 panic
    @inline
    func require(condition: bool, message: string) {
        if !condition {
            panic("Precondition failed: " + message);
        }
    }

    // ensure: 사후조건 검증
    // @ensure(condition) → condition이 거짓이면 panic
    @inline
    func ensure(condition: bool, message: string) {
        if !condition {
            panic("Postcondition failed: " + message);
        }
    }

    // invariant: 불변량 검증
    // @invariant(condition) → condition이 거짓이면 panic
    @inline
    func invariant(condition: bool, message: string) {
        if !condition {
            panic("Invariant violated: " + message);
        }
    }

    // ========================================================================
    // Zero-Copy DB 특화 안전성 계약
    // ========================================================================

    // PointerContract: 포인터 안전성 계약
    struct PointerContract {
        ptr: u64;
        buffer_start: u64;
        buffer_end: u64;
    }

    // verify_pointer_contract: 포인터 계약 검증
    // Precondition: buffer_start < buffer_end
    // Postcondition: buffer_start <= ptr <= buffer_end
    func verify_pointer_contract(contract: PointerContract) -> bool {
        // Precondition: 버퍼 경계가 올바르게 정의되었는가?
        if contract.buffer_start >= contract.buffer_end {
            panic("Precondition failed: buffer_start must be < buffer_end");
        }

        // Postcondition: 포인터가 범위 내인가?
        let in_bounds = contract.ptr >= contract.buffer_start && contract.ptr <= contract.buffer_end;
        if !in_bounds {
            panic("Postcondition failed: pointer out of bounds");
        }

        return true;
    }

    // ArrayAccessContract: 배열 접근 계약
    struct ArrayAccessContract {
        ptr: u64;
        index: u64;
        element_size: u64;
        array_length: u64;
    }

    // verify_array_access_contract: 배열 접근 계약 검증
    // Precondition: index >= 0, element_size > 0
    // Postcondition: ptr + (index * element_size) <= buffer_end
    func verify_array_access_contract(contract: ArrayAccessContract) -> bool {
        // Precondition 1: element_size > 0
        if contract.element_size == 0 {
            panic("Precondition failed: element_size must be > 0");
        }

        // Precondition 2: index < array_length
        if contract.index >= contract.array_length {
            panic("Precondition failed: index out of bounds");
        }

        // Postcondition: 계산된 주소가 유효한가?
        let calculated_offset = contract.index * contract.element_size;
        let calculated_ptr = contract.ptr + calculated_offset;

        // 오버플로우 체크
        if calculated_ptr < contract.ptr {
            panic("Postcondition failed: pointer arithmetic overflow");
        }

        return true;
    }

    // MemoryAllocationContract: 메모리 할당 계약
    struct MemoryAllocationContract {
        size: u64;
        alignment: u32;
        allocated_ptr: u64;
        allocated_size: u64;
    }

    // verify_allocation_contract: 메모리 할당 계약 검증
    // Precondition: size > 0, alignment > 0 (2의 거듭제곱)
    // Postcondition: 할당된 메모리가 정렬되었는가? allocated_ptr % alignment == 0
    func verify_allocation_contract(contract: MemoryAllocationContract) -> bool {
        // Precondition 1: size > 0
        if contract.size == 0 {
            panic("Precondition failed: allocation size must be > 0");
        }

        // Precondition 2: alignment > 0
        if contract.alignment == 0 {
            panic("Precondition failed: alignment must be > 0");
        }

        // Precondition 3: alignment이 2의 거듭제곱인가?
        let is_pow2 = (contract.alignment & (contract.alignment - 1)) == 0;
        if !is_pow2 {
            panic("Precondition failed: alignment must be power of 2");
        }

        // Postcondition 1: 할당된 크기가 요청 크기 이상
        if contract.allocated_size < contract.size {
            panic("Postcondition failed: allocated_size < requested_size");
        }

        // Postcondition 2: 포인터가 정렬되었는가?
        let aligned = contract.allocated_ptr % u64(contract.alignment);
        if aligned != 0 {
            panic("Postcondition failed: allocated pointer not aligned");
        }

        return true;
    }

    // ========================================================================
    // ContractChecker
    // ========================================================================

    // checker_new: 새로운 검증기 생성
    func checker_new() -> ContractChecker {
        return ContractChecker {
            violations: make([ContractViolation], 0),
            function_depth: 0,
            is_checking: true,
        };
    }

    // checker_record_violation: 계약 위반 기록
    func (c: *ContractChecker) checker_record_violation(
        violation_type: u32,
        function_name: string,
        condition: string,
        actual_value: string,
        expected_value: string
    ) {
        if !c.is_checking {
            return;
        }

        let message = if violation_type == VIOLATION_PRECONDITION {
            "Precondition violated"
        } else if violation_type == VIOLATION_POSTCONDITION {
            "Postcondition violated"
        } else {
            "Invariant violated"
        };

        let violation = ContractViolation {
            violation_type: violation_type,
            function_name: function_name,
            condition: condition,
            actual_value: actual_value,
            expected_value: expected_value,
            message: message,
        };

        c.violations.push(violation);
    }

    // checker_enter_function: 함수 진입
    // 불변량 검증
    func (c: *ContractChecker) checker_enter_function(function_name: string) {
        if !c.is_checking {
            return;
        }
        c.function_depth = c.function_depth + 1;
        // 불변량 검증 로직이 여기에 추가됨
    }

    // checker_exit_function: 함수 종료
    // 불변량 및 사후조건 검증
    func (c: *ContractChecker) checker_exit_function(function_name: string) {
        if !c.is_checking {
            return;
        }
        if c.function_depth > 0 {
            c.function_depth = c.function_depth - 1;
        }
    }

    // checker_has_violations: 계약 위반이 있는가?
    func (c: *ContractChecker) checker_has_violations() -> bool {
        return len(c.violations) > 0;
    }

    // checker_get_violations: 모든 위반 반환
    func (c: *ContractChecker) checker_get_violations() -> [ContractViolation] {
        return c.violations;
    }

    // checker_report: 위반 리포트
    func (c: *ContractChecker) checker_report() {
        if len(c.violations) == 0 {
            print("✅ Contract Checker: All contracts verified!");
            return;
        }

        print("❌ Contract Checker: Found " + len(c.violations) + " contract violation(s)");
        print("");

        for i = 0; i < len(c.violations); i = i + 1 {
            let v = c.violations[i];
            let type_str = if v.violation_type == VIOLATION_PRECONDITION {
                "Precondition"
            } else if v.violation_type == VIOLATION_POSTCONDITION {
                "Postcondition"
            } else {
                "Invariant"
            };

            print("Violation #" + (i + 1) + ":");
            print("  Function: " + v.function_name);
            print("  Type: " + type_str);
            print("  Condition: " + v.condition);
            print("  Expected: " + v.expected_value);
            print("  Actual: " + v.actual_value);
            print("  Message: " + v.message);
            print("");
        }
    }

    // ========================================================================
    // 함수 계약 예시
    // ========================================================================

    // buffer_copy: 안전한 버퍼 복사
    // @require(src_ptr != 0)
    // @require(dst_ptr != 0)
    // @require(size > 0)
    // @require(src_ptr + size <= src_end)
    // @require(dst_ptr + size <= dst_end)
    // @ensure(destination has been modified)
    @inline
    func buffer_copy(
        src_ptr: u64, src_end: u64,
        dst_ptr: u64, dst_end: u64,
        size: u64
    ) -> bool {
        // Precondition: src_ptr이 0이 아닌가?
        if src_ptr == 0 {
            panic("Precondition failed: src_ptr must not be null");
        }

        // Precondition: dst_ptr이 0이 아닌가?
        if dst_ptr == 0 {
            panic("Precondition failed: dst_ptr must not be null");
        }

        // Precondition: size > 0?
        if size == 0 {
            panic("Precondition failed: size must be > 0");
        }

        // Precondition: src 범위 검증
        if src_ptr + size > src_end {
            panic("Precondition failed: source buffer overflow");
        }

        // Precondition: dst 범위 검증
        if dst_ptr + size > dst_end {
            panic("Precondition failed: destination buffer overflow");
        }

        // 실제 복사 (simulation)
        // memcpy(dst_ptr, src_ptr, size);

        // Postcondition: 복사가 수행되었는가?
        // (실제로는 메모리 비교로 검증)

        return true;
    }

    // safe_vector_access: 안전한 벡터 접근
    // @require(vec != null)
    // @require(index < vec.count)
    // @ensure(returned value is valid)
    func safe_vector_access(index: u64, count: u64) -> bool {
        // Precondition: index < count?
        if index >= count {
            panic("Precondition failed: array index out of bounds");
        }

        // 접근 수행
        // let element = vec.data[index];

        return true;
    }
}

// ============================================================================
// 테스트 코드
// ============================================================================

func main() {
    print("🚀 FVX Safety Annotations 테스트");
    print("====================================");
    print("");

    // 테스트 1: 기본 require
    print("✅ 테스트 1: Precondition 검증");
    fvx.require(true, "Test condition is true");
    print("   require(true) passed");

    // 테스트 2: 포인터 계약
    print("✅ 테스트 2: Pointer Contract");
    let contract = fvx.PointerContract {
        ptr: 5000,
        buffer_start: 1000,
        buffer_end: 10000,
    };
    let valid = fvx.verify_pointer_contract(contract);
    print("   Pointer contract verified: " + valid);
    print("");

    // 테스트 3: 배열 접근 계약
    print("✅ 테스트 3: Array Access Contract");
    let array_contract = fvx.ArrayAccessContract {
        ptr: 1000,
        index: 10,
        element_size: 8,
        array_length: 100,
    };
    let array_valid = fvx.verify_array_access_contract(array_contract);
    print("   Array access contract verified: " + array_valid);
    print("");

    // 테스트 4: 메모리 할당 계약
    print("✅ 테스트 4: Memory Allocation Contract");
    let alloc_contract = fvx.MemoryAllocationContract {
        size: 1024,
        alignment: 64,
        allocated_ptr: 4096,  // 64로 정렬됨
        allocated_size: 1024,
    };
    let alloc_valid = fvx.verify_allocation_contract(alloc_contract);
    print("   Allocation contract verified: " + alloc_valid);
    print("");

    // 테스트 5: ContractChecker
    print("✅ 테스트 5: Contract Checker");
    let checker = fvx.checker_new();

    checker.checker_enter_function("test_function");
    print("   Entered function: test_function");

    // 위반 기록
    checker.checker_record_violation(
        fvx.VIOLATION_PRECONDITION,
        "test_function",
        "ptr != null",
        "0",
        "non-zero"
    );

    checker.checker_exit_function("test_function");
    print("   Exited function: test_function");
    print("");

    // 테스트 6: 리포트
    print("✅ 테스트 6: Contract Report");
    checker.checker_report();

    print("");
    print("✨ FVX Safety Annotations 테스트 완료!");
}

