// 구현:
//   - WebhookPayload: Git 이벤트 정보
//   - TestRunner: 자동 테스트 실행
//   - BenchmarkRunner: 벤치마크 실행 및 기록
//   - ResultReporter: 결과 보고
// ============================================================================

module gogs {
    // ========================================================================
    // Webhook Payload (Git 이벤트)
    // ========================================================================

    // WebhookPayload는 GOGS에서 전달되는 데이터
    struct WebhookPayload {
        event_type: string;     // push, pull_request, issues
        repository: string;     // 저장소 이름
        branch: string;         // 브랜치 (e.g., master, develop)
        commit_sha: string;     // 커밋 SHA-256
        commit_message: string;
        author: string;         // 작성자
        timestamp: string;      // ISO 8601 시간
    }

