    func (r: *ResultReporter) reporter_print() {
        print("╔════════════════════════════════════════════╗");
        print("║ Automated Test & Benchmark Report         ║");
        print("╚════════════════════════════════════════════╝");
        print("");

        print("Commit: " + r.commit_sha);
        print("Branch: " + r.branch);
        print("");

        print("━━━ Test Results ━━━");
        let test_passed = 0;
        for i = 0; i < len(r.test_results); i = i + 1 {
            let test = r.test_results[i];
            if test.status == 0 {
                test_passed = test_passed + 1;
            }
            let status = if test.status == 0 { "✅" } else { "❌" };
