        }

        print("");
        print("━━━ Benchmark Results ━━━");
        for i = 0; i < len(r.benchmark_results); i = i + 1 {
            let bench = r.benchmark_results[i];
            print("📊 " + bench.benchmark_name);
            print("   Throughput: " + bench.throughput + " ops/sec");
            print("   Improvement: +" + bench.improvement + "%");
        }

        print("");
        print("Summary: " + test_passed + "/" + len(r.test_results) + " tests passed");
        print("");
