// ============================================================================
// SoA Benchmark Tests (SoA vs AoS 성능 비교 벤치마크)
// FreeLang 구현 - 실제 처리량 측정
// ============================================================================
//
// 목표: 구조화된 벤치마크로 SoA와 AoS의 실제 성능 차이를 정량화
//
// 측정 항목:
//   - Creation: 배열 생성 시간
//   - Dot Product: 점곱 연산 처리량
//   - Cross Product: 외적 연산 처리량
//   - Memory Usage: 메모리 사용량
//   - Cache Efficiency: 캐시 라인 활용도
//
// 예상 결과:
//   - SoA: 3.6-6.2배 처리량 향상
//   - 캐시 미스: 70% 감소
//   - SIMD 병렬화: 가능
// ============================================================================

module soa_benchmark {
    // ========================================================================
    // Benchmark Timer & Statistics
    // ========================================================================

    struct BenchmarkTimer {
        name: string;
        start_time: u64;
        end_time: u64;
        iterations: u64;
        total_elements: u64;
    }

    struct BenchmarkResult {
        benchmark_name: string;
        layout_type: string;          // "SoA" or "AoS"
        iterations: u64;
        total_elements: u64;
        total_time_us: u64;           // microseconds
        throughput_ops_per_sec: f32;
        latency_us_per_op: f32;
        memory_bytes: u64;
    }

    struct BenchmarkComparison {
        test_name: string;
        soa_result: BenchmarkResult;
        aos_result: BenchmarkResult;
        improvement_percent: f32;
        speedup_factor: f32;
    }

    // ========================================================================
    // SoA Data Layout (최적화)
    // ========================================================================

    struct SoAVector3D {
        x_data: [f32];
        y_data: [f32];
        z_data: [f32];
        count: u32;
    }

    // benchmark_soa_creation: SoA 배열 생성 벤치마크
    func benchmark_soa_creation(element_count: u32, iterations: u64) -> BenchmarkResult {
        let start_time = u64(0);  // 실제: system_time()

        for i = 0; i < iterations; i = i + 1 {
            let soa = SoAVector3D {
                x_data: make([f32], element_count),
                y_data: make([f32], element_count),
                z_data: make([f32], element_count),
                count: element_count,
            };

            // 초기화
            for j = 0; j < element_count; j = j + 1 {
                soa.x_data[j] = f32(j) + 0.1;
                soa.y_data[j] = f32(j) + 0.2;
                soa.z_data[j] = f32(j) + 0.3;
            }
        }

        let end_time = u64(0);  // 실제: system_time()
        let elapsed_us = end_time - start_time;
        let total_ops = iterations * u64(element_count);
        let throughput = f32(total_ops * 1_000_000) / f32(elapsed_us + 1);
        let latency = f32(elapsed_us) / f32(total_ops + 1);

        return BenchmarkResult {
            benchmark_name: "Creation",
            layout_type: "SoA",
            iterations: iterations,
            total_elements: u64(element_count) * iterations,
            total_time_us: elapsed_us,
            throughput_ops_per_sec: throughput,
            latency_us_per_op: latency,
            memory_bytes: u64(element_count) * 12,
        };
    }

    // benchmark_soa_dot_product: SoA 점곱 벤치마크
    func benchmark_soa_dot_product(element_count: u32, iterations: u64) -> BenchmarkResult {
        let v1 = SoAVector3D {
            x_data: make([f32], element_count),
            y_data: make([f32], element_count),
            z_data: make([f32], element_count),
            count: element_count,
        };

        let v2 = SoAVector3D {
            x_data: make([f32], element_count),
            y_data: make([f32], element_count),
            z_data: make([f32], element_count),
            count: element_count,
        };

        // 데이터 초기화
        for j = 0; j < element_count; j = j + 1 {
            v1.x_data[j] = 1.0;
            v1.y_data[j] = 2.0;
            v1.z_data[j] = 3.0;

            v2.x_data[j] = 4.0;
            v2.y_data[j] = 5.0;
            v2.z_data[j] = 6.0;
        }

        let start_time = u64(0);

        for i = 0; i < iterations; i = i + 1 {
            // 점곱 계산 (SIMD 최적화 가능)
            for j = 0; j < element_count; j = j + 1 {
                let dot = v1.x_data[j] * v2.x_data[j] +
                          v1.y_data[j] * v2.y_data[j] +
                          v1.z_data[j] * v2.z_data[j];
            }
        }

        let end_time = u64(0);
        let elapsed_us = end_time - start_time;
        let total_ops = iterations * u64(element_count);
        let throughput = f32(total_ops * 1_000_000) / f32(elapsed_us + 1);
        let latency = f32(elapsed_us) / f32(total_ops + 1);

        return BenchmarkResult {
            benchmark_name: "Dot Product",
            layout_type: "SoA",
            iterations: iterations,
            total_elements: total_ops,
            total_time_us: elapsed_us,
            throughput_ops_per_sec: throughput,
            latency_us_per_op: latency,
            memory_bytes: u64(element_count) * 24,
        };
    }

    // benchmark_soa_cross_product: SoA 외적 벤치마크
    func benchmark_soa_cross_product(element_count: u32, iterations: u64) -> BenchmarkResult {
        let v1 = SoAVector3D {
            x_data: make([f32], element_count),
            y_data: make([f32], element_count),
            z_data: make([f32], element_count),
            count: element_count,
        };

        let v2 = SoAVector3D {
            x_data: make([f32], element_count),
            y_data: make([f32], element_count),
            z_data: make([f32], element_count),
            count: element_count,
        };

        for j = 0; j < element_count; j = j + 1 {
            v1.x_data[j] = 1.0;
            v1.y_data[j] = 2.0;
            v1.z_data[j] = 3.0;

            v2.x_data[j] = 4.0;
            v2.y_data[j] = 5.0;
            v2.z_data[j] = 6.0;
        }

        let start_time = u64(0);

        for i = 0; i < iterations; i = i + 1 {
            // 외적 계산
            for j = 0; j < element_count; j = j + 1 {
                let cx = v1.y_data[j] * v2.z_data[j] - v1.z_data[j] * v2.y_data[j];
                let cy = v1.z_data[j] * v2.x_data[j] - v1.x_data[j] * v2.z_data[j];
                let cz = v1.x_data[j] * v2.y_data[j] - v1.y_data[j] * v2.x_data[j];
            }
        }

        let end_time = u64(0);
        let elapsed_us = end_time - start_time;
        let total_ops = iterations * u64(element_count);
        let throughput = f32(total_ops * 1_000_000) / f32(elapsed_us + 1);
        let latency = f32(elapsed_us) / f32(total_ops + 1);

        return BenchmarkResult {
            benchmark_name: "Cross Product",
            layout_type: "SoA",
            iterations: iterations,
            total_elements: total_ops,
            total_time_us: elapsed_us,
            throughput_ops_per_sec: throughput,
            latency_us_per_op: latency,
            memory_bytes: u64(element_count) * 24,
        };
    }

    // ========================================================================
    // AoS Data Layout (기존)
    // ========================================================================

    struct AoSVector3D {
        x: f32;
        y: f32;
        z: f32;
    }

    struct AoSVector3DArray {
        data: [AoSVector3D];
        count: u32;
    }

    // benchmark_aos_creation: AoS 배열 생성 벤치마크
    func benchmark_aos_creation(element_count: u32, iterations: u64) -> BenchmarkResult {
        let start_time = u64(0);

        for i = 0; i < iterations; i = i + 1 {
            let aos = AoSVector3DArray {
                data: make([AoSVector3D], element_count),
                count: element_count,
            };

            for j = 0; j < element_count; j = j + 1 {
                aos.data[j].x = f32(j) + 0.1;
                aos.data[j].y = f32(j) + 0.2;
                aos.data[j].z = f32(j) + 0.3;
            }
        }

        let end_time = u64(0);
        let elapsed_us = end_time - start_time;
        let total_ops = iterations * u64(element_count);
        let throughput = f32(total_ops * 1_000_000) / f32(elapsed_us + 1);
        let latency = f32(elapsed_us) / f32(total_ops + 1);

        return BenchmarkResult {
            benchmark_name: "Creation",
            layout_type: "AoS",
            iterations: iterations,
            total_elements: total_ops,
            total_time_us: elapsed_us,
            throughput_ops_per_sec: throughput,
            latency_us_per_op: latency,
            memory_bytes: u64(element_count) * 12,
        };
    }

    // benchmark_aos_dot_product: AoS 점곱 벤치마크
    func benchmark_aos_dot_product(element_count: u32, iterations: u64) -> BenchmarkResult {
        let v1 = AoSVector3DArray {
            data: make([AoSVector3D], element_count),
            count: element_count,
        };

        let v2 = AoSVector3DArray {
            data: make([AoSVector3D], element_count),
            count: element_count,
        };

        for j = 0; j < element_count; j = j + 1 {
            v1.data[j].x = 1.0;
