        };
    }

    // ========================================================================
    // 리포팅
    // ========================================================================

    // report_result: 벤치마크 결과 출력
    func report_result(result: BenchmarkResult) {
        print("📊 " + result.benchmark_name + " (" + result.layout_type + ")");
        print("   Iterations: " + result.iterations);
        print("   Elements: " + result.total_elements);
        print("   Time: " + result.total_time_us + " μs");
