    @inline
    func check_array_access(array_size: u64, index: u64) -> (bool, BoundaryViolation) {
        // 정적 검증: index < array_size
        if index >= array_size {
            let violation = BoundaryViolation {
                violation_type: VIOLATION_OUT_OF_BOUNDS,
                buffer_name: "array",
                attempted_access: index,
                buffer_start: 0,
                buffer_end: array_size,
                message: "Array index " + index + " out of bounds (size: " + array_size + ")",
            };
            return (false, violation);
        }

        let violation = BoundaryViolation {
            violation_type: 0,
            buffer_name: "array",
            attempted_access: index,
            buffer_start: 0,
            buffer_end: array_size,
            message: "OK",
        };
        return (true, violation);
    }

    // check_pointer_arithmetic: 포인터 연산 정적 검증
