        print("📊 Summary: " + violation_count + " violations detected");
        print("   Expected: >= 3 violations");
        print("   Status: " + if violation_count >= 3 { "✅ PASS" } else { "❌ FAIL" });

        return violation_count >= 3;
    }
}

