        if len(a.violations) > 0 {
            print("⚠️  VIOLATIONS FOUND: " + len(a.violations));
            for i = 0; i < len(a.violations); i = i + 1 {
                let violation = a.violations[i];
                print("   [Violation #" + (i + 1) + "]");
                print("   Type: " + violation.violation_type);
                print("   Buffer: " + violation.buffer_name);
                print("   Attempted: " + violation.attempted_access);
                print("   Valid Range: [" + violation.buffer_start + ", " + violation.buffer_end + "]");
                print("   Message: " + violation.message);
                print("");
            }
        } else {
            print("✅ NO VIOLATIONS - All pointer accesses are safe!");
        }

        print("");
    }

    // ========================================================================
    // 부정 테스트 (Negative Test)
    // ========================================================================

    // test_intentional_violations: 일부러 위반 주입
    func test_intentional_violations() -> bool {
        print("🧪 Negative Test: Intentional Boundary Violations");
        print("================================================");
        print("");

        let analyzer = analyzer_new();

        // 버퍼 등록 (100개 요소, 각 4바이트 float)
        analyzer.analyzer_register_buffer("vec3_array", 400, 100, 4);

        print("Registered buffer: vec3_array (100 elements)");
        print("");

        // 테스트 1: 정상 접근
        print("Test 1: Valid Access (index 50)");
        let ok1 = analyzer.analyzer_check_array_access("vec3_array", 50);
        print("   Result: " + if ok1 { "✅ PASS" } else { "❌ FAIL" });
        print("");

        // 테스트 2: 범위 초과
        print("Test 2: Out of Bounds (index 150)");
        let ok2 = analyzer.analyzer_check_array_access("vec3_array", 150);
        print("   Result: " + if ok2 { "✅ PASS (not caught)" } else { "❌ FAIL (caught)" });
        print("");

        // 테스트 3: 포인터 오버플로우
        print("Test 3: Pointer Overflow (base 0, offset +500)");
        let ok3 = analyzer.analyzer_check_pointer_arithmetic("vec3_array", 0, 500);
        print("   Result: " + if ok3 { "✅ PASS (not caught)" } else { "❌ FAIL (caught)" });
        print("");

        // 테스트 4: 포인터 언더플로우
        print("Test 4: Pointer Underflow (base 0, offset -100)");
        let ok4 = analyzer.analyzer_check_pointer_arithmetic("vec3_array", 0, -100);
        print("   Result: " + if ok4 { "✅ PASS (not caught)" } else { "❌ FAIL (caught)" });
        print("");

        // 테스트 5: 슬라이스 범위 위반
        print("Test 5: Invalid Slice (start 50, end 150)");
        let (ok5, _) = check_slice_range(50, 150, 100);
        print("   Result: " + if ok5 { "✅ PASS (not caught)" } else { "❌ FAIL (caught)" });
        print("");

        // 리포트
        analyzer.analyzer_report();

        // 결과: 적어도 3개 이상의 위반이 감지되어야 함
        let violation_count = len(analyzer.violations);
        print("📊 Summary: " + violation_count + " violations detected");
        print("   Expected: >= 3 violations");
        print("   Status: " + if violation_count >= 3 { "✅ PASS" } else { "❌ FAIL" });

        return violation_count >= 3;
    }
}

// ============================================================================
// 메인 테스트
// ============================================================================

func main() {
    print("");
    print("╔════════════════════════════════════════════════════════╗");
    print("║ Static Boundary Checker - Compile-Time Verification   ║");
    print("╚════════════════════════════════════════════════════════╝");
    print("");

    // 부정 테스트 실행
    let test_result = boundary_static.test_intentional_violations();

    print("");
    print("╔════════════════════════════════════════════════════════╗");
